"""Meeting summaries and action items, generated by the local LLM (llm.py).

Short transcripts go to the model in one request. Long ones are summarized in
chunks first (map), and the chunk notes are then condensed into the final notes
(reduce), so any meeting length fits a small local model's context window.

Output (stored as JSON on the meeting):
    {"summary": str, "decisions": [str], "action_items": [{"task", "owner", "due", "done"}]}
"""
import json
import re

import config
import llm

SYSTEM = (
    "You are a meeting assistant. You write concise, factual meeting notes from a "
    "transcript. Write in the same language as the transcript. Never invent facts, "
    "names, or dates that are not in the transcript."
)

CHUNK_PROMPT = (
    "This is part {i} of {n} of a meeting transcript. Write compact bullet-point "
    "notes covering the topics discussed, decisions made, and any tasks someone "
    "agreed or was asked to do (with who and when, if stated).\n\n{text}"
)

FINAL_PROMPT = (
    "{intro}\n\n{text}\n\n"
    "Respond with ONLY a JSON object, no other text, in this exact shape:\n"
    '{{"summary": "one or two short paragraphs", '
    '"decisions": ["decision", "..."], '
    '"action_items": [{{"task": "what to do", "owner": "who (or empty)", "due": "when (or empty)"}}]}}\n'
    "Use empty lists when there are no decisions or action items. Use the speaker "
    "names exactly as they appear in the transcript for owners."
)


def fmt_offset(sec):
    sec = int(sec)
    return f"{sec // 3600}:{sec % 3600 // 60:02d}:{sec % 60:02d}" if sec >= 3600 else f"{sec // 60}:{sec % 60:02d}"


def transcript_lines(segments):
    out = []
    for s in segments:
        stamp = f"[{fmt_offset(s['start_sec'])}] " if s["start_sec"] is not None else ""
        out.append(f"{stamp}{s['speaker']}: {s['text']}")
    return out


def _chunks(lines, max_chars):
    chunk, size = [], 0
    for line in lines:
        if chunk and size + len(line) > max_chars:
            yield "\n".join(chunk)
            chunk, size = [], 0
        chunk.append(line)
        size += len(line) + 1
    if chunk:
        yield "\n".join(chunk)


def _ask(prompt):
    return llm.chat_completion(
        [{"role": "system", "content": SYSTEM}, {"role": "user", "content": prompt}],
        temperature=0.2,
        timeout=(3, config.SUMMARY_TIMEOUT_SEC),
    )


def parse_notes(reply):
    """Best-effort parse of the model's JSON; falls back to the raw text as summary."""
    text = re.sub(r"^```(?:json)?|```$", "", reply.strip(), flags=re.M).strip()
    start, end = text.find("{"), text.rfind("}")
    data = None
    if start != -1 and end > start:
        try:
            data = json.loads(text[start:end + 1])
        except ValueError:
            data = None
    if not isinstance(data, dict):
        return {"summary": reply.strip(), "decisions": [], "action_items": []}

    def strs(v):
        return [str(x).strip() for x in v if str(x).strip()] if isinstance(v, list) else []

    items = []
    for it in data.get("action_items") or []:
        if isinstance(it, str):
            it = {"task": it}
        if isinstance(it, dict) and str(it.get("task", "")).strip():
            items.append({
                "task": str(it.get("task", "")).strip(),
                "owner": str(it.get("owner") or "").strip(),
                "due": str(it.get("due") or "").strip(),
                "done": False,
            })
    return {
        "summary": str(data.get("summary") or "").strip(),
        "decisions": strs(data.get("decisions")),
        "action_items": items,
    }


def summarize(segments, on_progress=lambda detail: None):
    lines = transcript_lines(segments)
    if not lines:
        raise ValueError("this meeting has no transcript yet")
    chunks = list(_chunks(lines, config.SUMMARY_CHUNK_CHARS))
    if len(chunks) == 1:
        intro = "Here is a meeting transcript:"
        material = chunks[0]
    else:
        notes = []
        for i, chunk in enumerate(chunks, 1):
            on_progress(f"part {i}/{len(chunks)}")
            notes.append(f"Notes from part {i}:\n" + _ask(CHUNK_PROMPT.format(i=i, n=len(chunks), text=chunk)))
        intro = "Here are notes taken from consecutive parts of one meeting:"
        material = "\n\n".join(notes)
    on_progress("writing notes")
    return parse_notes(_ask(FINAL_PROMPT.format(intro=intro, text=material)))
